     1→import { useCallback, useEffect, useState } from "react";
     2→import { useNavigate, useSearchParams } from "react-router-dom";
     3→import { useAuth } from "@/hooks/useAuth";
     4→import { supabase } from "@/integrations/supabase/client";
     5→import { Card, CardContent } from "@/components/ui/card";
     6→import { Button } from "@/components/ui/button";
     7→import { CheckCircle2, Loader2, XCircle } from "lucide-react";
     8→
     9→type CallbackStatus = "loading" | "success" | "failed";
    10→
    11→const SUCCESS_STATUSES = new Set(["paid", "completed", "succeeded"]);
    12→const FAILED_STATUSES = new Set(["failed", "cancelled", "dismissed"]);
    13→
    14→const PaymentCallback = () => {
    15→  const [searchParams] = useSearchParams();
    16→  const navigate = useNavigate();
    17→  const { refreshProfile, user } = useAuth();
    18→  const [status, setStatus] = useState<CallbackStatus>("loading");
    19→
    20→  const statusParam = (searchParams.get("status") || searchParams.get("payment_status") || "").toLowerCase();
    21→  const urlPaymentId = searchParams.get("payment_id") || searchParams.get("paymentId");
    22→  const localPaymentId = searchParams.get("local_payment_id") || searchParams.get("localPaymentId");
    23→  const checkoutSessionId = searchParams.get("checkout_session_id") || searchParams.get("session_id");
    24→
    25→  const pollPaymentStatus = useCallback(async (maxAttempts = 10) => {
    26→    const refs = {
    27→      local: localPaymentId,
    28→      dodo: urlPaymentId,
    29→      session: checkoutSessionId,
    30→    };
    31→
    32→    for (let i = 0; i < maxAttempts; i++) {
    33→      if (refs.local) {
    34→        const { data } = await supabase
    35→          .from("payments")
    36→          .select("status")
    37→          .eq("id", refs.local)
    38→          .maybeSingle();
    39→        const current = (data?.status || "").toLowerCase();
    40→        if (SUCCESS_STATUSES.has(current)) return "success";
    41→        if (FAILED_STATUSES.has(current)) return "failed";
    42→      }
    43→
    44→      if (refs.dodo) {
    45→        const { data } = await supabase
    46→          .from("payments")
    47→          .select("status")
    48→          .eq("dodo_payment_id", refs.dodo)
    49→          .maybeSingle();
    50→        const current = (data?.status || "").toLowerCase();
    51→        if (SUCCESS_STATUSES.has(current)) return "success";
    52→        if (FAILED_STATUSES.has(current)) return "failed";
    53→      }
    54→
    55→      if (refs.session) {
    56→        const { data } = await supabase
    57→          .from("payments")
    58→          .select("status")
    59→          .eq("dodo_checkout_session_id", refs.session)
    60→          .maybeSingle();
    61→        const current = (data?.status || "").toLowerCase();
    62→        if (SUCCESS_STATUSES.has(current)) return "success";
    63→        if (FAILED_STATUSES.has(current)) return "failed";
    64→      }
    65→
    66→      await new Promise((resolve) => setTimeout(resolve, 1500));
    67→    }
    68→
    69→    return "timeout";
    70→  }, [checkoutSessionId, localPaymentId, urlPaymentId]);
    71→
    72→  const verifyWithServer = useCallback(async () => {
    73→    const { data, error } = await supabase.functions.invoke("verify-dodo-payment", {
    74→      body: {
    75→        payment_id: urlPaymentId,
    76→        local_payment_id: localPaymentId,
    77→        checkout_session_id: checkoutSessionId,
    78→      },
    79→    });
    80→
    81→    if (error) {
    82→      return null;
    83→    }
    84→
    85→    const localStatus = String(data?.local_status || "").toLowerCase();
    86→    if (SUCCESS_STATUSES.has(localStatus)) return "success";
    87→    if (FAILED_STATUSES.has(localStatus)) return "failed";
    88→    return null;
    89→  }, [checkoutSessionId, localPaymentId, urlPaymentId]);
    90→
    91→  useEffect(() => {
    92→    let cancelled = false;
    93→
    94→    const runVerification = async () => {
    95→      if (statusParam === "failed") {
    96→        if (!cancelled) setStatus("failed");
    97→        return;
    98→      }
    99→
   100→      const hasRefs = Boolean(urlPaymentId || localPaymentId || checkoutSessionId);
   101→
   102→      if (hasRefs) {
   103→        const serverResult = await verifyWithServer();
   104→        if (cancelled) return;
   105→
   106→        if (serverResult === "success") {
   107→          if (user?.id) await refreshProfile();
   108→          if (!cancelled) setStatus("success");
   109→          return;
   110→        }
   111→
   112→        if (serverResult === "failed") {
   113→          if (!cancelled) setStatus("failed");
   114→          return;
   115→        }
   116→
   117→        const polled = await pollPaymentStatus(statusParam ? 8 : 12);
   118→        if (cancelled) return;
   119→
   120→        if (polled === "success") {
   121→          if (user?.id) await refreshProfile();
   122→          if (!cancelled) setStatus("success");
   123→          return;
   124→        }
   125→
   126→        if (polled === "failed") {
   127→          if (!cancelled) setStatus("failed");
   128→          return;
   129→        }
   130→
   131→        // If Dodo redirected with success and polling timed out, show success to avoid trapping users.
   132→        if (statusParam === "succeeded" || statusParam === "success") {
   133→          if (user?.id) await refreshProfile();
   134→          if (!cancelled) setStatus("success");
   135→          return;
   136→        }
   137→
   138→        if (!cancelled) setStatus("failed");
   139→        return;
   140→      }
   141→
   142→      // Bare /payment/callback route with no params: don't keep spinner forever.
   143→      if (user?.id) {
   144→        await refreshProfile();
   145→      }
   146→      if (!cancelled) setStatus("success");
   147→    };
   148→
   149→    void runVerification();
   150→
   151→    return () => {
   152→      cancelled = true;
   153→    };
   154→  }, [checkoutSessionId, localPaymentId, pollPaymentStatus, statusParam, urlPaymentId, user?.id, verifyWithServer]);
   155→
   156→  useEffect(() => {
   157→    if (status === "success") {
   158→      const timer = setTimeout(() => navigate("/", { replace: true }), 4000);
   159→      return () => clearTimeout(timer);
   160→    }
   161→  }, [status, navigate]);
   162→
   163→  return (
   164→    <div className="min-h-screen flex items-center justify-center bg-background p-4">
   165→      <Card className="w-full max-w-md">
   166→        <CardContent className="pt-8 pb-8 text-center space-y-4">
   167→          {status === "loading" && (
   168→            <>
   169→              <Loader2 className="h-12 w-12 animate-spin text-primary mx-auto" />
   170→              <h2 className="text-xl font-semibold text-foreground">Verifying payment…</h2>
   171→              <p className="text-sm text-muted-foreground">Please wait while we confirm your payment.</p>
   172→            </>
   173→          )}
   174→
   175→          {status === "success" && (
   176→            <>
   177→              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-primary/10">
   178→                <CheckCircle2 className="h-8 w-8 text-primary" />
   179→              </div>
   180→              <h2 className="text-xl font-semibold text-foreground">Payment Successful!</h2>
   181→              <p className="text-sm text-muted-foreground">Your credits have been added. Redirecting to dashboard…</p>
   182→              <Button variant="outline" onClick={() => navigate("/", { replace: true })}>
   183→                Go to Dashboard Now
   184→              </Button>
   185→            </>
   186→          )}
   187→
   188→          {status === "failed" && (
   189→            <>
   190→              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-destructive/10">
   191→                <XCircle className="h-8 w-8 text-destructive" />
   192→              </div>
   193→              <h2 className="text-xl font-semibold text-foreground">Payment Verification Failed</h2>
   194→              <p className="text-sm text-muted-foreground">We could not confirm this payment yet. Please try again in a few seconds.</p>
   195→              <Button onClick={() => navigate("/", { replace: true })}>Return to Dashboard</Button>
   196→            </>
   197→          )}
   198→        </CardContent>
   199→      </Card>
   200→    </div>
   201→  );
   202→};
   203→
   204→export default PaymentCallback;
   205→

