     3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
     4→
     5→const corsHeaders = {
     6→  "Access-Control-Allow-Origin": "*",
     7→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
     8→};
     9→
    10→const PAID_STATUSES = new Set(["paid", "completed", "succeeded", "success"]);
    11→const FAILED_STATUSES = new Set(["failed", "cancelled", "canceled", "dismissed"]);
    12→
    13→const toLocalStatus = (raw: string | null | undefined) => {
    14→  const normalized = (raw || "").toLowerCase();
    15→  if (PAID_STATUSES.has(normalized)) return "paid";
    16→  if (FAILED_STATUSES.has(normalized)) return normalized === "canceled" ? "cancelled" : normalized;
    17→  return null;
    18→};
    19→
    20→Deno.serve(async (req) => {
    21→  if (req.method === "OPTIONS") {
    22→    return new Response(null, { headers: corsHeaders });
    23→  }
    24→
    25→  try {
    26→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
    27→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY");
    28→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    29→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    30→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    31→
    32→    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SUPABASE_SERVICE_ROLE_KEY || !DODO_API_KEY) {
    33→      return new Response(JSON.stringify({ error: "Server configuration error" }), {
    34→        status: 500,
    35→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    36→      });
    37→    }
    38→
    39→    const authHeader = req.headers.get("Authorization");
    40→    if (!authHeader) {
    41→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    42→        status: 401,
    43→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    44→      });
    45→    }
    46→
    47→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    48→      global: { headers: { Authorization: authHeader } },
    49→    });
    50→
    51→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    52→    if (userError || !user) {
    53→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    54→        status: 401,
    55→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    56→      });
    57→    }
    58→
    59→    const body = await req.json().catch(() => ({}));
    60→    const paymentId = typeof body.payment_id === "string" ? body.payment_id : null;
    61→    const localPaymentId = typeof body.local_payment_id === "string" ? body.local_payment_id : null;
    62→    const checkoutSessionIdInput = typeof body.checkout_session_id === "string" ? body.checkout_session_id : null;
    63→
    64→    if (!paymentId && !localPaymentId && !checkoutSessionIdInput) {
    65→      return new Response(JSON.stringify({ error: "payment_id, local_payment_id, or checkout_session_id is required" }), {
    66→        status: 400,
    67→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    68→      });
    69→    }
    70→
    71→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    72→
    73→    const baseUrl = DODO_ENV === "live_mode"
    74→      ? "https://live.dodopayments.com"
    75→      : "https://test.dodopayments.com";
    76→
    77→    let dodoPayment: Record<string, any> | null = null;
    78→
    79→    if (paymentId) {
    80→      const paymentResponse = await fetch(`${baseUrl}/payments/${encodeURIComponent(paymentId)}`, {
    81→        method: "GET",
    82→        headers: {
    83→          Authorization: `Bearer ${DODO_API_KEY}`,
    84→          "Content-Type": "application/json",
    85→        },
    86→      });
    87→
    88→      if (paymentResponse.ok) {
    89→        dodoPayment = await paymentResponse.json();
    90→      } else {
    91→        const errorText = await paymentResponse.text();
    92→        console.error("Failed to fetch Dodo payment:", paymentResponse.status, errorText);
    93→      }
    94→    }
    95→
    96→    const resolvedPaymentId = paymentId || dodoPayment?.payment_id || dodoPayment?.id || null;
    97→    const resolvedCheckoutSessionId = checkoutSessionIdInput || dodoPayment?.checkout_session_id || null;
    98→
    99→    let paymentRow: Record<string, any> | null = null;
   100→
   101→    if (localPaymentId) {
   102→      const { data } = await supabase
   103→        .from("payments")
   104→        .select("*")
   105→        .eq("id", localPaymentId)
   106→        .eq("user_id", user.id)
   107→        .maybeSingle();
   108→      paymentRow = data || null;
   109→    }
   110→
   111→    if (!paymentRow && resolvedPaymentId) {
   112→      const { data } = await supabase
   113→        .from("payments")
   114→        .select("*")
   115→        .eq("dodo_payment_id", resolvedPaymentId)
   116→        .eq("user_id", user.id)
   117→        .maybeSingle();
   118→      paymentRow = data || null;
   119→    }
   120→
   121→    if (!paymentRow && resolvedCheckoutSessionId) {
   122→      const { data } = await supabase
   123→        .from("payments")
   124→        .select("*")
   125→        .eq("dodo_checkout_session_id", resolvedCheckoutSessionId)
   126→        .eq("user_id", user.id)
   127→        .maybeSingle();
   128→      paymentRow = data || null;
   129→    }
   130→
   131→    if (!paymentRow) {
   132→      return new Response(JSON.stringify({ error: "Payment record not found for current user" }), {
   133→        status: 404,
   134→        headers: { ...corsHeaders, "Content-Type": "application/json" },
   135→      });
   136→    }
   137→
   138→    const dodoStatus = toLocalStatus(dodoPayment?.status);
   139→    const updatePayload: Record<string, any> = {};
   140→
   141→    if (resolvedPaymentId && paymentRow.dodo_payment_id !== resolvedPaymentId) {
   142→      updatePayload.dodo_payment_id = resolvedPaymentId;
   143→    }
   144→
   145→    if (resolvedCheckoutSessionId && paymentRow.dodo_checkout_session_id !== resolvedCheckoutSessionId) {
   146→      updatePayload.dodo_checkout_session_id = resolvedCheckoutSessionId;
   147→    }
   148→
   149→    if (Object.keys(updatePayload).length > 0) {
   150→      await supabase.from("payments").update(updatePayload).eq("id", paymentRow.id);
   151→    }
   152→
   153→    let becamePaid = false;
   154→    let finalStatus = paymentRow.status;
   155→
   156→    if (dodoStatus === "paid") {
   157→      const { data: paidUpdate } = await supabase
   158→        .from("payments")
   159→        .update({
   160→          status: "paid",
   161→          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
   162→          ...(resolvedCheckoutSessionId ? { dodo_checkout_session_id: resolvedCheckoutSessionId } : {}),
   163→        })
   164→        .eq("id", paymentRow.id)
   165→        .neq("status", "paid")
   166→        .select("id")
   167→        .maybeSingle();
   168→
   169→      becamePaid = !!paidUpdate;
   170→      finalStatus = "paid";
   171→
   172→      if (becamePaid) {
   173→        const { data: profile } = await supabase
   174→          .from("profiles")
   175→          .select("credits")
   176→          .eq("user_id", paymentRow.user_id)
   177→          .single();
   178→
   179→        if (profile) {
   180→          await supabase
   181→            .from("profiles")
   182→            .update({ credits: profile.credits + paymentRow.credits_purchased })
   183→            .eq("user_id", paymentRow.user_id);
   184→        }
   185→
   186→        if (paymentRow.plan_id) {
   187→          const { data: plan } = await supabase
   188→            .from("plans")
   189→            .select("name, billing_type")
   190→            .eq("id", paymentRow.plan_id)
   191→            .single();
   192→
   193→          if (plan) {
   194→            const endsAt = new Date();
   195→            if (plan.billing_type === "yearly") {
   196→              endsAt.setFullYear(endsAt.getFullYear() + 1);
   197→            } else {
   198→              endsAt.setMonth(endsAt.getMonth() + 1);
   199→            }
   200→
   201→            await supabase
   202→              .from("profiles")
   203→              .update({
   204→                plan: plan.name,
   205→                subscription_ends_at: endsAt.toISOString(),
   206→                ...(dodoPayment?.subscription_id ? { dodo_subscription_id: dodoPayment.subscription_id } : {}),
   207→              })
   208→              .eq("user_id", paymentRow.user_id);
   209→          }
   210→        }
   211→      }
   212→    } else if (dodoStatus && dodoStatus !== paymentRow.status) {
   213→      await supabase
   214→        .from("payments")
   215→        .update({ status: dodoStatus })
   216→        .eq("id", paymentRow.id);
   217→      finalStatus = dodoStatus;
   218→    }
   219→
   220→    return new Response(JSON.stringify({
   221→      success: true,
   222→      local_payment_id: paymentRow.id,
   223→      dodo_payment_id: resolvedPaymentId,
   224→      checkout_session_id: resolvedCheckoutSessionId,
   225→      dodo_status: dodoPayment?.status || null,
   226→      local_status: finalStatus,
   227→      credits_added: becamePaid,
   228→    }), {
   229→      headers: { ...corsHeaders, "Content-Type": "application/json" },
   230→    });
   231→  } catch (err: unknown) {
   232→    console.error("verify-dodo-payment error:", err);
   233→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
   234→      status: 500,
   235→      headers: { ...corsHeaders, "Content-Type": "application/json" },
   236→    });
   237→  }
   238→});
   239→

